    private hasSameMembership(nextKeys: Set<string>) {
        return nextKeys.size === this.selectedKeys.size && [...nextKeys].every((key) => this.selectedKeys.has(key))
    }

    private identitiesIntersecting(rectangle: DiagramRectangle) {
        const identities: DiagramSelectionIdentity[] = []
        for (const nodeId of this.session.getNodeIdsSnapshot()) {
            const box = this.readBox('node', nodeId)
            if (box && diagramRectangleIntersectsBox(rectangle, box)) {
                identities.push({ objectId: nodeId, objectKind: 'node' })
            }
        }
        for (const edgeId of this.session.getEdgeIdsSnapshot()) {
            if (diagramRectangleIntersectsRoute(rectangle, this.geometry.getEdgeRouteSnapshot(edgeId))) {
                identities.push({ objectId: edgeId, objectKind: 'edge' })
            }
        }
        for (const groupId of this.session.getGroupIdsSnapshot()) {
            const box = this.readBox('group', groupId)
            if (box && diagramRectangleIntersectsBox(rectangle, box)) {
                identities.push({ objectId: groupId, objectKind: 'group' })
            }
        }

        return identities
    }

    private readBox(objectKind: 'group' | 'node', objectId: string): DiagramRectangle | null {
        const getField = objectKind === 'node'
            ? this.geometry.getNodeGeometryFieldSnapshot
            : this.geometry.getGroupGeometryFieldSnapshot
        const height = getField(objectId, 'height')
        const width = getField(objectId, 'width')
        const x = getField(objectId, 'x')
        const y = getField(objectId, 'y')
        if (height === null || width === null || x === null || y === null) return null

        return { height, width, x, y }
    }

    private requireSelectableIdentity(identity: DiagramSelectionIdentity) {
        if (!this.session.getSessionSnapshot()) throw new Error('Cannot select a diagram object without an active edit session')
        if (identity.objectKind === 'edge' && this.session.getEdgeSnapshot(identity.objectId)) return
        if (identity.objectKind === 'group' && this.session.getGroupSnapshot(identity.objectId)) return
        if (identity.objectKind === 'node' && this.session.getNodeSnapshot(identity.objectId)) return

        throw new Error(`Diagram ${identity.objectKind} ${identity.objectId} does not exist`)
    }

    private clearRectangle() {
        if (!this.rectangleStart && !this.rectangle) return false

        this.rectangleStart = null
        this.rectangle = null
        this.dispatchEvent(new Event(SELECTION_RECTANGLE_CHANGED_EVENT))

        return true
    }

    private setRectangle(rectangle: DiagramRectangle) {
        const current = this.rectangle
        if (current && current.height === rectangle.height && current.width === rectangle.width
            && current.x === rectangle.x && current.y === rectangle.y) return false

        this.rectangle = rectangle
        this.dispatchEvent(new Event(SELECTION_RECTANGLE_CHANGED_EVENT))

        return true
    }

    private publish(changedIdentities: readonly DiagramSelectionIdentity[]) {
        for (const identity of changedIdentities) this.dispatchEvent(new Event(selectedChangedEvent(identity)))
        this.dispatchEvent(new Event(SELECTION_MEMBERSHIP_CHANGED_EVENT))
    }

    private subscribe(eventType: string, listener: () => void) {
        this.addEventListener(eventType, listener)

        return () => this.removeEventListener(eventType, listener)
    }
}

export const diagramSelectionService = register('diagramSelectionService', new DiagramSelectionService())

import { Box, Typography } from '@mui/material'
import { useRef, type MouseEvent, type PointerEvent, type ReactNode } from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import {
    diagramSelectionService, type DiagramSelectionService,
} from '../../services/diagrams/diagram_selection_service'
import {
    EditableDiagramActivations,
    EditableDiagramEdges,
    EditableDiagramFragments,
    EditableDiagramGroups,
    EditableDiagramLifelines,
    EditableDiagramNodes,
} from './editable_diagram_collections'
import { convertClientToDiagramCoordinates } from './diagram_coordinate_conversion'
import { DiagramSelectionRectangle } from './diagram_selection_rectangle'
import { useDiagramSurfaceField } from './use_diagram_geometry'
import { useEditableDiagramMetadataField } from './use_editable_diagram'

interface EditableDiagramProps {
    geometry?: DiagramGeometryService
    selection?: DiagramSelectionService
    session?: DiagramEditSessionService
}

interface MetadataLeafProps {
    session?: DiagramEditSessionService
}

/** Title of the New diagram; it observes that one metadata field. */
export function EditableDiagramTitle({ session = diagramEditSessionService }: MetadataLeafProps) {
    return <Typography variant="h6">{useEditableDiagramMetadataField('title', session) ?? ''}</Typography>
}

/** Description of the New diagram; it observes that one metadata field. */
export function EditableDiagramDescription({ session = diagramEditSessionService }: MetadataLeafProps) {
    return (
        <Typography color="text.secondary" variant="body2">
            {useEditableDiagramMetadataField('description', session) ?? ''}
        </Typography>
    )
}

/**
 * Sizes the New drawing surface. Its children arrive as an element through `children`, so a surface bound change
 * resizes the box without rerendering the collection hosts inside it.
 */
export function EditableDiagramSurface({
    children,
    geometry = diagramGeometryService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: {
    children: ReactNode,
    geometry?: DiagramGeometryService,
    selection?: DiagramSelectionService,
    session?: DiagramEditSessionService,
}) {
    const height = useDiagramSurfaceField('height', geometry)
    const width = useDiagramSurfaceField('width', geometry)
    const activePointerIdRef = useRef<number | null>(null)
    const suppressNextClickRef = useRef(false)
    const diagramPointFromPointer = (event: PointerEvent<HTMLDivElement>) => {
        const bounds = event.currentTarget.getBoundingClientRect()
        const viewportMetrics = { bounds: { left: bounds.left, top: bounds.top }, scrollLeft: 0, scrollTop: 0 }

        return convertClientToDiagramCoordinates(event, viewportMetrics, session.getViewportScaleSnapshot()).diagramPoint
    }
    const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
        if (event.button !== 0 || session.getActiveToolSnapshot() !== 'select') return
        if ((event.target as Element).closest('[data-diagram-id]')) return

        event.preventDefault()
        activePointerIdRef.current = event.pointerId
        suppressNextClickRef.current = false
        selection.beginRectangleSelection(diagramPointFromPointer(event))
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }
    const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
        if (activePointerIdRef.current !== event.pointerId) return

        selection.updateRectangleSelection(diagramPointFromPointer(event))
    }
    const releasePointer = (event: PointerEvent<HTMLDivElement>) => {
        if (event.currentTarget.hasPointerCapture?.(event.pointerId)) {
            event.currentTarget.releasePointerCapture?.(event.pointerId)
        }
        activePointerIdRef.current = null
    }
    const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
        if (activePointerIdRef.current !== event.pointerId) return

        selection.completeRectangleSelection(diagramPointFromPointer(event))
        suppressNextClickRef.current = true
        releasePointer(event)
    }
    const handlePointerCancel = (event: PointerEvent<HTMLDivElement>) => {
        if (activePointerIdRef.current !== event.pointerId) return

        selection.cancelRectangleSelection()
        releasePointer(event)
    }
    const handleClick = (event: MouseEvent<HTMLDivElement>) => {
        if (suppressNextClickRef.current) {
            suppressNextClickRef.current = false

            return
        }
        if (session.getActiveToolSnapshot() !== 'select') return
        if ((event.target as Element).closest('[data-diagram-id]')) return

        selection.clear()
    }

    return (
        <Box
            aria-label="New diagram"
            onClick={handleClick}
            onPointerCancel={handlePointerCancel}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            sx={{ height, position: 'relative', touchAction: 'none', width }}
        >
            {children}
        </Box>
    )
}

/**
 * Root of the New diagram. It composes stable hosts and leaves and subscribes to no diagram state itself, so no
 * edit inside the diagram can rerender it.
 */
export function EditableDiagram({
    geometry = diagramGeometryService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: EditableDiagramProps) {
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
            <Box>
                <EditableDiagramTitle session={session} />
                <EditableDiagramDescription session={session} />
            </Box>
            <EditableDiagramSurface geometry={geometry} selection={selection} session={session}>
                <EditableDiagramGroups geometry={geometry} selection={selection} session={session} />
                <EditableDiagramFragments geometry={geometry} session={session} />
                <EditableDiagramLifelines geometry={geometry} session={session} />
                <EditableDiagramActivations geometry={geometry} session={session} />
                <EditableDiagramEdges geometry={geometry} selection={selection} session={session} />
                <EditableDiagramNodes geometry={geometry} selection={selection} session={session} />
                <DiagramSelectionRectangle selection={selection} />
            </EditableDiagramSurface>
        </Box>
    )
}

import { memo } from 'react'
import type { DiagramEntityField } from '../../services/diagrams/diagram_data'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramNode } from '../../services/diagrams/diagram_layout'
import {
    diagramSelectionService, type DiagramSelectionService,
} from '../../services/diagrams/diagram_selection_service'
import { DiagramNode } from './diagram_node'
import { useDiagramNodeGeometryField } from './use_diagram_geometry'
import { useIsDiagramObjectSelected } from './use_diagram_selection'
import { useEditableDiagramMetadataField, useEditableDiagramNodeField } from './use_editable_diagram'

interface EditableDiagramNodeProps {
    geometry?: DiagramGeometryService
    nodeId: string
    selection?: DiagramSelectionService
    session?: DiagramEditSessionService
}

/**
 * One node of the New diagram. Every value it renders arrives through its own field subscription, so an edit to a
 * sibling node, an edge, a group, or the metadata cannot rerender this leaf.
 */
function EditableDiagramNodeLeaf({
    geometry = diagramGeometryService,
    nodeId,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: EditableDiagramNodeProps) {
    const diagramType = useEditableDiagramMetadataField('type', session)
    const preset = useEditableDiagramMetadataField('preset', session)
    const fields = useEditableDiagramNodeField(nodeId, 'fields', session)
    const kind = useEditableDiagramNodeField(nodeId, 'kind', session)
    const label = useEditableDiagramNodeField(nodeId, 'label', session)
    const role = useEditableDiagramNodeField(nodeId, 'role', session)
    const sublabel = useEditableDiagramNodeField(nodeId, 'sublabel', session)
    const tag = useEditableDiagramNodeField(nodeId, 'tag', session)
    const fanIn = useDiagramNodeGeometryField(nodeId, 'fanIn', geometry)
    const height = useDiagramNodeGeometryField(nodeId, 'height', geometry)
    const width = useDiagramNodeGeometryField(nodeId, 'width', geometry)
    const x = useDiagramNodeGeometryField(nodeId, 'x', geometry)
    const y = useDiagramNodeGeometryField(nodeId, 'y', geometry)
    const selected = useIsDiagramObjectSelected(nodeId, 'node', selection)
    if (!diagramType || label === null || role === null || width === null || height === null) return null

    const handleSelect = (_selection: unknown, ctrlKey: boolean) => {
        if (session.getActiveToolSnapshot() !== 'select') return

        const identity = { objectId: nodeId, objectKind: 'node' } as const
        if (ctrlKey) {
            selection.toggle(identity)
            return
        }
        selection.replace([identity])
    }

    const node: PositionedDiagramNode = {
        fanIn: fanIn ?? 0,
        height,
        id: nodeId,
        label,
        role,
        width,
        x: x ?? 0,
        y: y ?? 0,
        ...(fields ? { fields: fields as DiagramEntityField[] } : {}),
        ...(kind ? { kind } : {}),
        ...(sublabel ? { sublabel } : {}),
        ...(tag ? { tag } : {}),
    }

    return (
        <DiagramNode
            diagramType={diagramType}
            flowPreset={preset ?? undefined}
            node={node}
            onSelect={handleSelect}
            selected={selected}
        />
    )
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramNode = memo(EditableDiagramNodeLeaf)

import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import {
    diagramSelectionService, type DiagramSelectionService,
} from '../../services/diagrams/diagram_selection_service'
import { EditableDiagramActivation } from './editable_diagram_activation'
import { EditableDiagramEdge } from './editable_diagram_edge'
import { EditableDiagramFragment } from './editable_diagram_fragment'
import { EditableDiagramGroup } from './editable_diagram_group'
import { EditableDiagramLifeline } from './editable_diagram_lifeline'
import { EditableDiagramNode } from './editable_diagram_node'
import { useDiagramActivationIds, useDiagramFragmentIds } from './use_diagram_geometry'
import {
    useEditableDiagramEdgeIds, useEditableDiagramGroupIds, useEditableDiagramNodeIds,
} from './use_editable_diagram'

interface CollectionHostProps {
    geometry?: DiagramGeometryService
    session?: DiagramEditSessionService
}

interface SelectableCollectionHostProps extends CollectionHostProps {
    selection?: DiagramSelectionService
}

/**
 * Every host below observes one ordered identifier list and nothing else. A field edit inside a member changes no
 * identifier list, so the host is skipped and only the member leaf rerenders.
 */
export function EditableDiagramNodes({
    geometry = diagramGeometryService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: SelectableCollectionHostProps) {
    const nodeIds = useEditableDiagramNodeIds(session)

    return nodeIds.map((nodeId) => (
        <EditableDiagramNode geometry={geometry} key={nodeId} nodeId={nodeId} selection={selection} session={session} />
    ))
}

export function EditableDiagramLifelines({
    geometry = diagramGeometryService,
    session = diagramEditSessionService,
}: CollectionHostProps) {
    const nodeIds = useEditableDiagramNodeIds(session)

    return nodeIds.map((nodeId) => (
        <EditableDiagramLifeline geometry={geometry} key={nodeId} nodeId={nodeId} session={session} />
    ))
}

export function EditableDiagramEdges({
    geometry = diagramGeometryService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: SelectableCollectionHostProps) {
    const edgeIds = useEditableDiagramEdgeIds(session)

    return (
        <svg
            aria-label="New diagram connections"
            height="100%"
            style={{ left: 0, overflow: 'visible', pointerEvents: 'none', position: 'absolute', top: 0, zIndex: 1 }}
            width="100%"
        >
            {edgeIds.map((edgeId) => (
                <EditableDiagramEdge edgeId={edgeId} geometry={geometry} key={edgeId} selection={selection} session={session} />
            ))}
        </svg>
    )
}

export function EditableDiagramGroups({
    geometry = diagramGeometryService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: SelectableCollectionHostProps) {
    const groupIds = useEditableDiagramGroupIds(session)

    return groupIds.map((groupId) => (
        <EditableDiagramGroup geometry={geometry} groupId={groupId} key={groupId} selection={selection} session={session} />
    ))
}

export function EditableDiagramFragments({
    geometry = diagramGeometryService,
    session = diagramEditSessionService,
}: CollectionHostProps) {
    const fragmentIds = useDiagramFragmentIds(geometry)

    return fragmentIds.map((fragmentId) => (
        <EditableDiagramFragment fragmentId={fragmentId} geometry={geometry} key={fragmentId} session={session} />
    ))
}

export function EditableDiagramActivations({ geometry = diagramGeometryService }: CollectionHostProps) {
    const activationIds = useDiagramActivationIds(geometry)

    return activationIds.map((activationId) => (
        <EditableDiagramActivation activationId={activationId} geometry={geometry} key={activationId} />
    ))
}

import { memo } from 'react'
import type { DiagramWaypoint } from '../../services/diagrams/diagram_data'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramEdge } from '../../services/diagrams/diagram_layout'
import {
    diagramSelectionService, type DiagramSelectionService,
} from '../../services/diagrams/diagram_selection_service'
import { DiagramEdge } from './diagram_edge'
import { useDiagramEdgeLabelPlacement, useDiagramEdgeRoute } from './use_diagram_geometry'
import { useIsDiagramObjectSelected } from './use_diagram_selection'
import { useEditableDiagramEdgeField } from './use_editable_diagram'

const EMPTY_NODE_LABELS: ReadonlyMap<string, string> = new Map()

interface EditableDiagramEdgeProps {
    edgeId: string
    geometry?: DiagramGeometryService
    selection?: DiagramSelectionService
    session?: DiagramEditSessionService
}

/**
 * One connection of the New diagram. It observes its own model fields and its own derived route.
 */
function EditableDiagramEdgeLeaf({
    edgeId,
    geometry = diagramGeometryService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: EditableDiagramEdgeProps) {
    const from = useEditableDiagramEdgeField(edgeId, 'from', session)
    const fromCardinality = useEditableDiagramEdgeField(edgeId, 'fromCardinality', session)
    const kind = useEditableDiagramEdgeField(edgeId, 'kind', session)
    const label = useEditableDiagramEdgeField(edgeId, 'label', session)
    const to = useEditableDiagramEdgeField(edgeId, 'to', session)
    const toCardinality = useEditableDiagramEdgeField(edgeId, 'toCardinality', session)
    const labelPlacement = useDiagramEdgeLabelPlacement(edgeId, geometry)
    const points = useDiagramEdgeRoute(edgeId, geometry)
    const selected = useIsDiagramObjectSelected(edgeId, 'edge', selection)
    if (from === null || to === null || kind === null || points.length === 0) return null

    const handleSelect = (_selection: unknown, ctrlKey: boolean) => {
        if (session.getActiveToolSnapshot() !== 'select') return

        const identity = { objectId: edgeId, objectKind: 'edge' } as const
        if (ctrlKey) {
            selection.toggle(identity)
            return
        }
        selection.replace([identity])
    }

    const edge: PositionedDiagramEdge = {
        from,
        id: edgeId,
        kind,
        points: points as DiagramWaypoint[],
        to,
        ...(fromCardinality ? { fromCardinality } : {}),
        ...(label ? { label } : {}),
        ...(labelPlacement ? { labelPlacement } : {}),
        ...(toCardinality ? { toCardinality } : {}),
    }

    return <DiagramEdge edge={edge} nodeLabels={EMPTY_NODE_LABELS} onSelect={handleSelect} selected={selected} />
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramEdge = memo(EditableDiagramEdgeLeaf)

import { Box, ButtonBase, Typography } from '@mui/material'
import { useRef, type KeyboardEvent, type MouseEvent } from 'react'
import type { DiagramFlowPreset, DiagramType } from '../../services/diagrams/diagram_data'
import type { PositionedDiagramNode } from '../../services/diagrams/diagram_layout'
import { diagramRoleStyle } from './diagram_role_style'
import type { DiagramSelectHandler } from './diagram_selection'

interface DiagramNodeProps {
    diagramType: DiagramType
    flowPreset?: DiagramFlowPreset
    node: PositionedDiagramNode
    onSelect: DiagramSelectHandler
    selected: boolean
}

function kindStyles(node: PositionedDiagramNode, flowPreset: DiagramFlowPreset | undefined) {
    if (flowPreset === 'state' && node.kind === 'start') {
        return {bgcolor: 'text.primary', border: 0, borderRadius: 99} as const
    }
    if (flowPreset === 'state' && node.kind === 'end') {
        return {
            bgcolor: 'background.default', border: '2px solid', borderColor: 'text.primary', borderRadius: 99,
            '&::before': {
                bgcolor: 'text.primary', borderRadius: 99, content: '""', height: 10, left: 5,
                position: 'absolute', top: 5, width: 10,
            },
        } as const
    }
    if (node.kind === 'start' || node.kind === 'end') return { borderRadius: 99 }
    if (node.kind === 'decision') return { transform: 'rotate(45deg)', '& > *': { transform: 'rotate(-45deg)' } }

    return { borderRadius: node.kind === 'state' ? 1 : '6px' }
}

function fieldPrefix(key: 'primary' | 'foreign' | undefined) {
    if (key === 'primary') return '# '
    if (key === 'foreign') return 'â†’ '

    return ''
}

/** Positioned, themed, keyboard-operable diagram item. */
export function DiagramNode({ diagramType, flowPreset, node, onSelect, selected }: DiagramNodeProps) {
    const stateMarker = flowPreset === 'state' && (node.kind === 'start' || node.kind === 'end')
    const interactive = node.drilldown !== false
    const scrollRef = useRef<HTMLDivElement>(null)
    const pressScrollTop = useRef(0)
    const handleSelect = (left: number, top: number, ctrlKey: boolean) => (
        onSelect({ id: node.id, label: node.label, left, top }, ctrlKey)
    )
    const handleMouseDown = () => { pressScrollTop.current = scrollRef.current?.scrollTop ?? 0 }
    const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
        // A scrollbar drag inside the content area presses and releases on the button; that is a scroll, not a selection.
        if ((scrollRef.current?.scrollTop ?? 0) !== pressScrollTop.current) return
        handleSelect(event.clientX, event.clientY, event.ctrlKey)
    }
    const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
        if (event.key !== 'Enter' && event.key !== ' ') return
        event.preventDefault()
        const bounds = event.currentTarget.getBoundingClientRect()
        handleSelect(bounds.left, bounds.bottom, false)
    }

    return (
        <ButtonBase
            aria-label={node.label}
            aria-disabled={interactive ? undefined : true}
            aria-pressed={interactive ? selected : undefined}
            data-diagram-id={node.id}
            data-diagram-kind="node"
            onClick={interactive ? handleClick : undefined}
            onKeyDown={interactive ? handleKeyDown : undefined}
            onMouseDown={interactive ? handleMouseDown : undefined}
            role="button"
            sx={{
                alignItems: 'stretch', border: '1px solid', color: 'text.primary', display: 'flex', flexDirection: 'column',
                height: node.height, left: node.x, overflow: 'hidden', position: 'absolute', textAlign: 'left',
                top: node.y, width: node.width, zIndex: 2,
                ...diagramRoleStyle(node.role),
                ...kindStyles(node, flowPreset),
                ...(selected ? { outline: '2px solid', outlineColor: 'primary.main', outlineOffset: 2 } : {}),
                '&:focus-visible': { borderColor: 'primary.main', outline: '2px solid', outlineColor: 'primary.main', outlineOffset: 2 },
            }}
            tabIndex={interactive ? undefined : -1}
        >
            {!stateMarker ? (
                <Box
                    data-diagram-scroll="content"
                    ref={scrollRef}
                    sx={{
                        display: 'flex', flex: 1, flexDirection: 'column',
                        // `safe center` centres content that fits and falls back to top alignment once it overflows,
                        // so the tag and label stay reachable instead of being clipped above the scroll origin.
                        justifyContent: 'safe center', minHeight: 0, overflowX: 'hidden', overflowY: 'auto',
                    }}
                >
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, px: 2, py: 1 }}>
                        {node.tag ? <Typography color="custom.text3" variant="overline">{node.tag}</Typography> : null}
                        <Typography sx={{ fontWeight: 600, overflowWrap: 'anywhere' }} variant="body2">{node.label}</Typography>
                        {node.sublabel ? (
                            <Typography color="text.secondary" sx={{ overflowWrap: 'anywhere' }} variant="caption">{node.sublabel}</Typography>
                        ) : null}
                    </Box>
                    {diagramType === 'entity' && node.fields ? (
                        <Box sx={{ borderColor: 'divider', borderTop: '1px solid', display: 'flex', flexDirection: 'column', px: 2, py: 1 }}>
                            {node.fields.map((field) => (
                                <Typography key={`${field.key ?? 'field'}:${field.name}`} sx={{ fontFamily: 'monospace' }} variant="caption">
                                    {fieldPrefix(field.key)}{field.name}{field.type ? `: ${field.type}` : ''}
                                </Typography>
                            ))}
                        </Box>
                    ) : null}
                </Box>
            ) : null}
            {diagramType === 'dependency' ? (
                <Typography
                    color="text.secondary"
                    sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 0.25, position: 'absolute', px: 0.5, right: 1, top: 0.75 }}
                    variant="caption"
                >
                    {node.fanIn} in
                </Typography>
            ) : null}
        </ButtonBase>
    )
}

import { useId, useState, type KeyboardEvent, type MouseEvent } from 'react'
import { useTheme } from '@mui/material'
import type { PositionedDiagramEdge } from '../../services/diagrams/diagram_layout'
import { diagramEdgeStyle } from './diagram_edge_style'
import { roundedDiagramPath } from './diagram_path'
import type { DiagramSelectHandler } from './diagram_selection'

const EDGE_LABEL_FONT_SIZE = 8
interface DiagramEdgeProps {
    edge: PositionedDiagramEdge
    /** Endpoint labels only, so a subscribing caller can supply them without owning positioned node objects. */
    nodeLabels: ReadonlyMap<string, string>
    onSelect: DiagramSelectHandler
    selected: boolean
}

function edgeLabel(edge: PositionedDiagramEdge, nodeLabels: ReadonlyMap<string, string>) {
    const from = nodeLabels.get(edge.from) ?? edge.from
    const to = nodeLabels.get(edge.to) ?? edge.to

    return edge.label ?? `${from} to ${to}`
}

/** Themed selectable connection rendered from validated geometry. */
export function DiagramEdge({ edge, nodeLabels, onSelect, selected }: DiagramEdgeProps) {
    const theme = useTheme()
    const [focused, setFocused] = useState(false)
    const label = edgeLabel(edge, nodeLabels)
    const path = roundedDiagramPath(edge.points)
    const { arrowhead, color, strokeDasharray, strokeWidth } = diagramEdgeStyle(edge.kind, theme, focused || selected)
    const visibleLabel = edge.label ?? (edge.kind === 'cycle' ? 'CYCLE' : null)
    const markerId = `diagram-arrow-${useId().replace(/:/gu, '')}`
    const handleSelect = (left: number, top: number, ctrlKey: boolean) => (
        onSelect({ id: edge.id, label, left, top }, ctrlKey)
    )
    const handleClick = (event: MouseEvent<SVGGElement>) => handleSelect(event.clientX, event.clientY, event.ctrlKey)
    const handleKeyDown = (event: KeyboardEvent<SVGGElement>) => {
        if (event.key !== 'Enter' && event.key !== ' ') return
        event.preventDefault()
        const bounds = event.currentTarget.getBoundingClientRect()
        handleSelect(bounds.left, bounds.bottom, false)
    }
    const handleFocus = () => setFocused(true)
    const handleBlur = () => setFocused(false)
    const labelPoint = edge.labelPlacement

    return (
        <g
            aria-label={label}
            aria-pressed={selected}
            data-diagram-id={edge.id}
            data-diagram-kind="edge"
            onBlur={handleBlur}
            onClick={handleClick}
            onFocus={handleFocus}
            onKeyDown={handleKeyDown}
            role="button"
            style={{ color, cursor: 'pointer', outline: 'none', pointerEvents: 'auto' }}
            tabIndex={0}
        >
            <defs>
                <marker id={markerId} markerHeight="6" markerWidth="8" orient="auto" refX="7" refY="3">
                    {arrowhead === 'open'
                        ? <polyline fill="none" points="0 0, 8 3, 0 6" stroke="currentColor" strokeWidth="1.2" />
                        : <path d="M0,0 L8,3 L0,6 Z" fill="currentColor" />}
                </marker>
            </defs>
            <path d={path} fill="none" opacity={0} stroke="currentColor" strokeWidth={12} />
            <path
                d={path}
                fill="none"
                markerEnd={`url(#${markerId})`}
                stroke="currentColor"
                strokeDasharray={strokeDasharray}
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={strokeWidth}
            />
            {visibleLabel && labelPoint ? (
                <g>
                    <rect
                        fill={theme.palette.background.default}
                        height={labelPoint.height}
                        rx={2}
                        width={labelPoint.width}
                        x={labelPoint.x}
                        y={labelPoint.y}
                    />
                    <text
                        fill={color}
                        fontFamily="monospace"
                        fontSize={EDGE_LABEL_FONT_SIZE}
                        textAnchor="middle"
                        x={labelPoint.textX}
                        y={labelPoint.textY}
                    >
                        {visibleLabel}
                    </text>
                </g>
            ) : null}
            {edge.fromCardinality ? (
                <text fill={theme.palette.text.secondary} fontFamily="monospace" fontSize={EDGE_LABEL_FONT_SIZE} x={edge.points[0].x + 8} y={edge.points[0].y - 8}>
                    {edge.fromCardinality}
                </text>
            ) : null}
            {edge.toCardinality ? (
                <text
                    fill={theme.palette.text.secondary}
                    fontFamily="monospace"
                    fontSize={EDGE_LABEL_FONT_SIZE}
                    textAnchor="end"
                    x={(edge.points.at(-1)?.x ?? 0) - 8}
                    y={(edge.points.at(-1)?.y ?? 0) - 8}
                >
                    {edge.toCardinality}
                </text>
            ) : null}
        </g>
    )
}

import { Box, Typography } from '@mui/material'
import type { KeyboardEvent, MouseEvent } from 'react'
import type { PositionedDiagramGroup } from '../../services/diagrams/diagram_layout'

interface DiagramGroupProps {
    group: PositionedDiagramGroup
    onSelect?: (ctrlKey: boolean) => void
    selected?: boolean
}

/** Containment or trust-zone box; interactive only on the New diagram. */
export function DiagramGroup({ group, onSelect, selected = false }: DiagramGroupProps) {
    const interactive = !!onSelect
    const handleClick = (event: MouseEvent<HTMLButtonElement>) => onSelect?.(event.ctrlKey)
    const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
        if (event.key !== 'Enter' && event.key !== ' ') return
        event.preventDefault()
        onSelect?.(false)
    }

    return (
        <Box
            aria-label={group.label}
            aria-pressed={interactive ? selected : undefined}
            component={interactive ? 'button' : 'div'}
            data-diagram-id={interactive ? group.id : undefined}
            data-diagram-kind={interactive ? 'group' : undefined}
            onClick={interactive ? handleClick : undefined}
            onKeyDown={interactive ? handleKeyDown : undefined}
            role={interactive ? 'button' : 'group'}
            sx={{
                bgcolor: 'transparent', color: 'text.primary', cursor: interactive ? 'pointer' : 'default', font: 'inherit', p: 0,
                border: '1px dashed', borderColor: 'custom.borderStrong', borderRadius: 1, height: group.height, left: group.x,
                pointerEvents: interactive ? 'auto' : 'none', position: 'absolute', textAlign: 'left', top: group.y,
                width: group.width, zIndex: 0,
                ...(selected ? { outline: '2px solid', outlineColor: 'primary.main', outlineOffset: 2 } : {}),
                '&:focus-visible': interactive
                    ? { borderColor: 'primary.main', outline: '2px solid', outlineColor: 'primary.main', outlineOffset: 2 }
                    : {},
            }}
            type={interactive ? 'button' : undefined}
        >
            <Typography color="custom.text3" sx={{ bgcolor: 'background.default', left: 1, px: 0.5, position: 'absolute', top: 0.5 }} variant="overline">
                {group.label}
            </Typography>
        </Box>
    )
}

import { memo } from 'react'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramGroup } from '../../services/diagrams/diagram_layout'
import {
    diagramSelectionService, type DiagramSelectionService,
} from '../../services/diagrams/diagram_selection_service'
import { DiagramGroup } from './diagram_group'
import { useDiagramGroupGeometryField } from './use_diagram_geometry'
import { useIsDiagramObjectSelected } from './use_diagram_selection'
import { useEditableDiagramGroupField } from './use_editable_diagram'

interface EditableDiagramGroupProps {
    geometry?: DiagramGeometryService
    groupId: string
    selection?: DiagramSelectionService
    session?: DiagramEditSessionService
}

/** One containment box of the New diagram, bound to its own label and its own derived box. */
function EditableDiagramGroupLeaf({
    geometry = diagramGeometryService,
    groupId,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: EditableDiagramGroupProps) {
    const label = useEditableDiagramGroupField(groupId, 'label', session)
    const height = useDiagramGroupGeometryField(groupId, 'height', geometry)
    const width = useDiagramGroupGeometryField(groupId, 'width', geometry)
    const x = useDiagramGroupGeometryField(groupId, 'x', geometry)
    const y = useDiagramGroupGeometryField(groupId, 'y', geometry)
    const selected = useIsDiagramObjectSelected(groupId, 'group', selection)
    if (label === null || height === null || width === null) return null

    const handleSelect = (ctrlKey: boolean) => {
        if (session.getActiveToolSnapshot() !== 'select') return

        const identity = { objectId: groupId, objectKind: 'group' } as const
        if (ctrlKey) {
            selection.toggle(identity)
            return
        }
        selection.replace([identity])
    }

    // Membership is edited elsewhere and is not rendered by the box, so this view object carries no member IDs.
    const group: PositionedDiagramGroup = { height, id: groupId, label, nodeIds: [], width, x: x ?? 0, y: y ?? 0 }

    return <DiagramGroup group={group} onSelect={handleSelect} selected={selected} />
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramGroup = memo(EditableDiagramGroupLeaf)

