        })) return false

        fragment[field] = value
        const originalValue = this.originalFragmentsById.get(fragmentId)?.[field]
        const eventName = diagramObjectFieldChangedEvent('fragment', fragmentId, field)
        this.finishFieldChange(
            eventName,
            `fragment:${fragmentId}`,
