/** Subscribes one leaf to one edge connection-point field. */
export function useEditableDiagramConnectionPointField<Field extends keyof DiagramConnectionPoint>(
    edgeId: string,
    endpoint: DiagramConnectionEndpoint,
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeConnectionPointField(edgeId, endpoint, field, listener),
        [edgeId, endpoint, field, service],
    )
    const getSnapshot = useCallback(
        () => service.getConnectionPointFieldSnapshot(edgeId, endpoint, field),
        [edgeId, endpoint, field, service],
    )

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

function useEditableDiagramCollectionIds(
    objectKind: 'edge' | 'fragment' | 'group' | 'node',
    getSnapshot: () => readonly string[],
    service: DiagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeCollectionMembership(objectKind, listener),
        [objectKind, service],
    )

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

export function useEditableDiagramNodeIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useEditableDiagramCollectionIds('node', service.getNodeIdsSnapshot, service)
}

export function useEditableDiagramEdgeIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useEditableDiagramCollectionIds('edge', service.getEdgeIdsSnapshot, service)
}

export function useEditableDiagramGroupIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useEditableDiagramCollectionIds('group', service.getGroupIdsSnapshot, service)
}

export function useEditableDiagramFragmentIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useEditableDiagramCollectionIds('fragment', service.getFragmentIdsSnapshot, service)
}

/** Subscribes a review collection only to semantic change membership and order. */
export function useEditableDiagramChangeIds(service: DiagramEditSessionService = diagramEditSessionService) {
    return useDiagramSnapshot(service.subscribeChangeIds, service.getChangeIdsSnapshot, service)
}

/** Subscribes one review leaf to one field of one semantic change. */
export function useEditableDiagramChangeField<Field extends DiagramChangeField>(
    changeId: string,
    field: Field,
    service: DiagramEditSessionService = diagramEditSessionService,
) {
    const subscribe = useCallback(
        (listener: () => void) => service.subscribeChangeField(changeId, field, listener),
        [changeId, field, service],
    )
    const getSnapshot = useCallback(
        () => service.getChangeFieldSnapshot(changeId, field),
        [changeId, field, service],
    )

    return useDiagramSnapshot(subscribe, getSnapshot, service)
}

import { register } from './service_injector'
import { telemetryService } from './telemetry/telemetry_service'

export const DIALOG_SERVICE_EVENT = 'md2:dialog-message'

export type DialogSeverity = 'error' | 'warning' | 'info' | 'success'

export interface DialogServiceAction {
    callback(): Promise<void> | void
    label: string
}

export interface DialogServiceMessage {
    action?: DialogServiceAction
    critical: boolean
    id: number
    message: string
    severity: DialogSeverity
    title: string
}

export interface DialogServiceOptions {
    action?: DialogServiceAction
    critical?: boolean
    fallbackMessage?: string
    title?: string
}

const DEFAULT_TITLES: Record<DialogSeverity, string> = {
    error: 'Error',
    info: 'Information',
    success: 'Success',
    warning: 'Warning',
}

function messageFrom(value: unknown, fallbackMessage: string) {
    if (value instanceof Error && value.message.length > 0) return value.message
    if (typeof value === 'string' && value.length > 0) return value

    return fallbackMessage
}

/** Central notification service for user-visible messages and blocking dialogs. */
export class DialogService extends EventTarget {
    private nextId = 1

    constructor() {
        super()
        register('dialogService', this)
    }

    error(error: unknown, options: DialogServiceOptions = {}) {
        telemetryService.captureError(error)
        const message = messageFrom(error, options.fallbackMessage ?? 'An error occurred')

        return this.show('error', message, options)
    }

    /** Shows an expected user-facing error without reporting it as an application failure. */
    displayError(message: string, options: DialogServiceOptions = {}) {
        return this.show('error', message, options)
    }

    warning(message: string, options: DialogServiceOptions = {}) {
        return this.show('warning', message, options)
    }

    info(message: string, options: DialogServiceOptions = {}) {
        return this.show('info', message, options)
    }

    success(message: string, options: DialogServiceOptions = {}) {
        return this.show('success', message, options)
    }

    private show(severity: DialogSeverity, message: string, options: DialogServiceOptions) {
        if (message.length === 0) throw new Error('Dialog message is required')

        const dialogMessage = {
            ...(options.action ? { action: options.action } : {}),
            critical: !!options.critical,
            id: this.nextId,
            message,
            severity,
            title: options.title ?? DEFAULT_TITLES[severity],
        }
        this.nextId += 1
        this.dispatchEvent(new CustomEvent<DialogServiceMessage>(DIALOG_SERVICE_EVENT, { detail: dialogMessage }))

        return dialogMessage
    }
}

export const dialogService = new DialogService()

import { Box, Typography } from '@mui/material'
import { useRef } from 'react'
import type { PositionedDiagramData } from '../../services/diagrams/diagram_layout'
import { DiagramEdge } from './diagram_edge'
import { DiagramGroup } from './diagram_group'
import { DiagramNode } from './diagram_node'
import type { DiagramSelectHandler, DiagramSelection } from './diagram_selection'
import { SequenceActivation } from './sequence_activation'
import { SequenceFragment } from './sequence_fragment'

export interface DiagramProps {
    data: PositionedDiagramData
    onSelect: (anchorElement: HTMLElement, selection: DiagramSelection) => void
}

/** Diagram surface composed from validated semantic data and positioned React children. */
export function Diagram({ data, onSelect }: DiagramProps) {
    const surfaceRef = useRef<HTMLDivElement>(null)
    const nodeLabels = new Map(data.nodes.map((node) => [node.id, node.label]))
    const handleSelect: DiagramSelectHandler = (selection) => {
        if (surfaceRef.current) onSelect(surfaceRef.current, selection)
    }
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, minWidth: data.width }}>
            <Box>
                <Typography variant="h6">{data.meta.title}</Typography>
                <Typography color="text.secondary" variant="body2">{data.meta.description}</Typography>
            </Box>
            <Box
                aria-label={`${data.meta.title} diagram`}
                ref={surfaceRef}
                sx={{ height: data.height, position: 'relative', width: data.width }}
            >
                {data.groups.map((group) => <DiagramGroup group={group} key={group.id} />)}
                {data.fragments.map((fragment) => <SequenceFragment fragment={fragment} key={fragment.id} />)}
                {data.meta.type === 'sequence' ? data.nodes.map((node) => (
                    <Box key={`sequence-${node.id}`}>
                        <Box
                            sx={{ borderLeft: '1px dashed', borderColor: 'divider', height: data.height - 24 - node.y - node.height, left: node.x + node.width / 2, position: 'absolute', top: node.y + node.height, zIndex: 1 }}
                        />
                    </Box>
                )) : null}
                {data.activations.map((activation) => <SequenceActivation activation={activation} key={activation.id} />)}
                <svg aria-label="Diagram connections" height={data.height} style={{ left: 0, overflow: 'visible', position: 'absolute', top: 0, zIndex: 1 }} width={data.width}>
                    {data.edges.map((edge) => (
                        <DiagramEdge edge={edge} key={edge.id} nodeLabels={nodeLabels} onSelect={handleSelect} selected={false} />
                    ))}
                </svg>
                {data.nodes.map((node) => (
                    <DiagramNode
                        diagramType={data.meta.type}
                        flowPreset={data.meta.preset}
                        key={node.id}
                        node={node}
                        onSelect={handleSelect}
                        selected={false}
                    />
                ))}
            </Box>
        </Box>
    )
}

